static uint16_t bm_text_width_s(const char *s, glyph_t (*get)(uint16_t))
{
    uint16_t w = 0;
    while (*s) { glyph_t g = get((uint8_t)*s++); w = (uint16_t)(w + g.w + 1); }
    return w ? (uint16_t)(w - 1) : 0;
}
uint16_t bm_text_width_micro(const char *s) { return bm_text_width_s(s, bm_font_glyph_micro); }
uint16_t bm_text_width_expr(const char *s) { return bm_text_width_s(s, bm_font_glyph_expr); }
